PRAGMA foreign_keys = OFF;
BEGIN;
CREATE TABLE artifact_runs (id TEXT NOT NULL, run_id TEXT NOT NULL, node_id TEXT NOT NULL DEFAULT '', PRIMARY KEY (id, run_id, node_id));
CREATE TABLE artifacts (
          id TEXT PRIMARY KEY, kind TEXT NOT NULL, body_schema TEXT NOT NULL,
          classification TEXT NOT NULL, run_id TEXT, node_id TEXT, subject_ref TEXT,
          decision_type TEXT, envelope TEXT NOT NULL, created_at TEXT NOT NULL
        );
CREATE TABLE events (
        seq INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, type TEXT NOT NULL,
        run_id TEXT, node_id TEXT, session_id TEXT, turn_id TEXT, entry TEXT NOT NULL
      );
CREATE TABLE leases (
        resource TEXT PRIMARY KEY, owner TEXT, token TEXT, generation INTEGER NOT NULL, expires_at INTEGER,
        CHECK ((owner IS NULL AND token IS NULL AND expires_at IS NULL) OR (owner IS NOT NULL AND token IS NOT NULL AND expires_at IS NOT NULL))
      );
CREATE TABLE mailbox (session_id TEXT NOT NULL, seq INTEGER NOT NULL, sender TEXT NOT NULL, message_id TEXT NOT NULL, artifact TEXT NOT NULL, created_at TEXT NOT NULL,
        PRIMARY KEY (session_id, seq), UNIQUE (session_id, sender, message_id));
CREATE TABLE session_groups (group_id TEXT PRIMARY KEY, barrier_open INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE session_handoffs (session_id TEXT PRIMARY KEY, artifact TEXT NOT NULL);
CREATE TABLE system_migrations (owner TEXT NOT NULL, version INTEGER NOT NULL, applied_at TEXT NOT NULL, PRIMARY KEY (owner, version));
CREATE TABLE worker_sessions (session_id TEXT PRIMARY KEY, group_id TEXT, record TEXT NOT NULL, updated_at TEXT NOT NULL, last_active TEXT);
CREATE TABLE workflow_nodes (
    run_id TEXT NOT NULL, node_id TEXT NOT NULL, ordinal INTEGER NOT NULL, spec TEXT NOT NULL, record TEXT NOT NULL, state TEXT NOT NULL,
    prompt TEXT, execution_id TEXT, attempt INTEGER NOT NULL DEFAULT 0, not_before TEXT, worker TEXT, served_tier TEXT, quota_class TEXT,
    error TEXT, updated_at TEXT NOT NULL, decisions TEXT, source TEXT, escalations INTEGER NOT NULL DEFAULT 0, subject TEXT, PRIMARY KEY (run_id, node_id)
  );
CREATE TABLE workflow_runs (
    run_id TEXT PRIMARY KEY, request_key TEXT UNIQUE, template TEXT NOT NULL, spec_hash TEXT NOT NULL, input TEXT NOT NULL,
    classification TEXT, session_id TEXT, status TEXT NOT NULL, result TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
  );
CREATE TABLE workflow_wakes (run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, through_seq INTEGER NOT NULL, reply_to TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'wake');
CREATE INDEX artifacts_kind ON artifacts (kind, decision_type);
CREATE INDEX artifacts_run ON artifacts (run_id, node_id);
CREATE INDEX events_run ON events (run_id, seq);
CREATE INDEX events_session ON events (session_id, seq);
CREATE INDEX events_type ON events (type, seq);
CREATE INDEX worker_sessions_group ON worker_sessions (group_id);
CREATE INDEX workflow_runs_status ON workflow_runs (status);
